<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\PlatformIdentity\Domain;

use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Holder\PlatformIdentityUidAttributeHolder;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityUidVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Holder\PlatformIdentityUserAttributeHolder;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityUserVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Holder\PlatformIdentityRelyingPartyAttributeHolder;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRelyingPartyVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Holder\PlatformIdentityTrustedClientAttributeHolder;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityTrustedClientVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Holder\PlatformIdentityRolesAttributeHolder;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Holder\PlatformIdentityVersionAttributeHolder;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityVersionVO;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;

class PlatformIdentityAttributes
{
    use PlatformIdentityUidAttributeHolder;
    use PlatformIdentityUserAttributeHolder;
    use PlatformIdentityRelyingPartyAttributeHolder;
    use PlatformIdentityTrustedClientAttributeHolder;
    use PlatformIdentityRolesAttributeHolder;
    use PlatformIdentityVersionAttributeHolder;

    private const array UNSETS = [
      'uid' => 'unsetUid',
      'user' => 'unsetUser',
      'relyingParty' => 'unsetRelyingParty',
      'trustedClient' => 'unsetTrustedClient',
      'roles' => 'unsetRoles',
      'version' => 'unsetVersion',
    ];

    public function build(): PlatformIdentity
    {
        $errors = new ConstraintFailList();
        $uid = PlatformIdentityUidVO::tryFrom($this->uid, $errors);
        $user = PlatformIdentityUserVO::tryFrom($this->user, $errors);
        $relyingParty = PlatformIdentityRelyingPartyVO::tryFrom($this->relyingParty, $errors);
        $trustedClient = PlatformIdentityTrustedClientVO::tryFrom($this->trustedClient, $errors);
        $roles = PlatformIdentityRolesVO::tryFrom($this->roles, $errors);
        $version = PlatformIdentityVersionVO::tryFrom($this->version, $errors);
        if ($errors->hasErrors()) {
            throw $errors->asConstraintException();
        }
        \assert($uid !== null);
        \assert($user !== null);
        \assert($roles !== null);
        return new PlatformIdentity(
            uid: $uid,
            user: $user,
            relyingParty: $relyingParty,
            trustedClient: $trustedClient,
            roles: $roles,
            version: $version,
        );
    }
    public function withAssertedRules(): PlatformIdentityAttributes
    {
        $value = new PlatformIdentityAttributes();
        $errorsList = new ConstraintFailList();
        $this->withAssertedUidRules($value, $errorsList);
        $this->withAssertedUserRules($value, $errorsList);
        $this->withAssertedRelyingPartyRules($value, $errorsList);
        $this->withAssertedTrustedClientRules($value, $errorsList);
        $this->withAssertedRolesRules($value, $errorsList);
        $this->withAssertedVersionRules($value, $errorsList);
        if ($errorsList->hasErrors()) {
            throw $errorsList->asConstraintException();
        }
        return $value;
    }
    public function unset(string $field): void
    {
        if (isset(self::UNSETS[$field])) {
            call_user_func([$this, self::UNSETS[$field]]);
        }
    }
    public function withDefaults(): PlatformIdentityAttributes
    {
        $this->withDefaultUid();
        $this->withDefaultUser();
        $this->withDefaultRelyingParty();
        $this->withDefaultTrustedClient();
        $this->withDefaultRoles();
        $this->withDefaultVersion();
        return $this;
    }
}
